"""Полный локальный HTML-отчёт по фактическому снимку Pi и материалам проекта."""
import ast
import base64
from datetime import datetime
import hashlib
import html
import json
import os
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'outputs/go2-autonomy/full-audit-20260927'
SRC=ROOT/'work/go2-autonomy'
data=json.loads((OUT/'pi-inventory.json').read_text(encoding='utf-8-sig'))
def esc(v):return html.escape(str(v))
def pre(v):return '<pre>'+esc(v if isinstance(v,str) else json.dumps(v,ensure_ascii=False,indent=2))+'</pre>'
def table(headers,rows):
    return '<div class="table"><table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(p,label=None):
    p=Path(p)
    return '<a href="'+esc(os.path.relpath(p,OUT).replace('\\','/'))+'">'+esc(label or p.name)+'</a>'
def details(title,content):return '<details><summary>'+esc(title)+'</summary>'+content+'</details>'
def image(p,caption):
    if not p.exists():return ''
    mime='image/png' if p.suffix=='.png' else 'image/jpeg'
    return '<figure><img loading="lazy" alt="'+esc(caption)+'" src="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'"><figcaption>'+esc(caption)+'</figcaption></figure>'
sections=[]
def section(id,title,content):sections.append((id,title,'<section id="'+id+'"><h2>'+title+'</h2>'+content+'</section>'))

installed=json.loads(data['installed'])
latest=data['sessions']['autonomy_logs'][-1]
latest_report=latest.get('report.json',{})
streams=latest_report.get('sensor_report',{}).get('streams',{})
local_sessions=[]
recordings=ROOT/'outputs/go2-teleop/recordings/teleop_logs'
if recordings.exists():
    for folder in sorted(recordings.iterdir()):
        if folder.is_dir():
            fs=[p for p in folder.rglob('*') if p.is_file()]
            local_sessions.append({'name':folder.name,'files':len(fs),'bytes':sum(p.stat().st_size for p in fs)})
source_rows=[]
for p in sorted(SRC.rglob('*.py')):
    if any(x in p.parts for x in ('__pycache__','.venv','reference-go2-ros2')):continue
    if len(p.relative_to(SRC).parts)>3:continue
    try:doc=ast.get_docstring(ast.parse(p.read_text(encoding='utf-8-sig'))) or ''
    except Exception:doc='Не разобран AST'
    source_rows.append([str(p.relative_to(SRC)),doc.split('\n')[0],p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest()])
hash_rows=[]
for name,remote in data['release_hashes'].items():
    p=SRC/name
    current=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
    hash_rows.append([name,'Совпадает' if current==remote else 'Отличается / нет локального файла',remote,current or '—'])
(OUT/'local-inventory.json').write_text(json.dumps({'recordings':local_sessions,'source_files':source_rows,'release_comparison':hash_rows},ensure_ascii=False,indent=2),encoding='utf-8')

section('verdict','1. Итог без приукрашивания', '''
<div class="danger"><strong>Цель не достигнута: подтверждённого автономного прохождения ни одного препятствия и всей петли нет.</strong>
<p>Есть рабочее подключение, получение данных, ручные записи, ограниченные тесты движения и значительный объём программной логики. Готовой системы «нажал — робот сам прошёл полосу» сейчас нет.</p></div>
<p>Ответственность за незавершённую интеграцию и неэффективную последовательность разработки лежит на разработке. Пользователь предоставил доступ, наблюдение и ручные записи. Недостаток дополнительных разрешений не является причиной отсутствия результата.</p>
<div class="cards"><article><b>0</b>подтверждённых автономных препятствий</article><article><b>324</b>прошедших локальных теста логики</article><article><b>1</b>найденный успешный ручной проход рампы</article></div>
<p>324 теста — результат последнего выполненного запуска перед этим аудитом, а не новый прогон на роботе. Ни число тестов, ни наличие кнопок, ни факт установки пакета не являются проверкой автономности.</p>
<p>Этот отчёт относится к физическому Go2. Исторические результаты Webots L1 (52/52) относятся к другому решению и здесь не засчитываются.</p>''')
